    return strlen(key) + 1 + strlen(val);
}

int logfmt_append(char *buf, size_t buf_sz, const char *key, const char *val) {
    size_t len = strlen(buf);
    if (len + strlen(key) + 1 + strlen(val) + 2 >= buf_sz) return -1;
    buf[len++] = ' ';
    return _write_pair(&buf[len], buf_sz - len, key, val);
}
